"use client";

import React, { useState, useEffect } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Truck, ClipboardList } from "lucide-react";
import { toast } from "sonner";

import { backendFetch } from "@/lib/backendFetch";
import styles from "./create-dispatch.module.css";

interface Customer {
  id: string;
  companyName: string;
  billingAddress?: ShippingAddress | string | null;
  shippingAddress?: ShippingAddress | string | null;
}

interface ShippingAddress {
  addressLine1?: string;
  addressLine2?: string;
  line1?: string;
  line2?: string;
  street?: string;
  city?: string;
  state?: string;
  pincode?: string;
  pinCode?: string;
  zipCode?: string;
  postalCode?: string;
  country?: string;
}

interface SalesOrder {
  id: string;
  orderNumber: string;
  requestedDeliveryDate?: string;
  freightAmount?: string | number;
  shippingAddress?: ShippingAddress | string | null;
  customer?: Customer;
}

interface SalesOrderItem {
  id: string;
  productId: string;
  productNameSnapshot: string;
  orderedQuantity: number;
  unitPrice: number;
  dispatchItems?: { quantity: string | number }[];
}

interface ProductionPlan {
  id: string;
  salesOrder?: SalesOrder;
}

interface WorkOrder {
  id: string;
  workOrderNumber: string;
  quantity: number;
  status: string;
  salesOrderItemId: string;
  productionPlan?: ProductionPlan;
  salesOrderItem?: SalesOrderItem;
  qcInspections?: {
    approvedQuantity: string | number | null;
    approvedAt: string | null;
    createdAt: string;
  }[];
}

function formatAddressValue(value?: ShippingAddress | string | null): string {
  if (!value) return "";
  if (typeof value === "string") {
    try {
      return formatAddressValue(JSON.parse(value) as ShippingAddress);
    } catch {
      return value.trim();
    }
  }
  return [
    value.line1 || value.addressLine1 || value.street,
    value.line2 || value.addressLine2,
    value.city,
    value.state,
    value.postalCode || value.pincode || value.pinCode || value.zipCode,
    value.country,
  ]
    .filter(Boolean)
    .join(", ");
}

function availableQuantity(workOrder: WorkOrder): number {
  const approved = Number(
    workOrder.qcInspections?.[0]?.approvedQuantity ?? workOrder.quantity ?? 0,
  );
  const item = workOrder.salesOrderItem;
  const alreadyDispatched =
    item?.dispatchItems?.reduce(
      (sum, dispatchItem) => sum + Number(dispatchItem.quantity),
      0,
    ) || 0;
  const remainingOrder = Math.max(
    0,
    Number(item?.orderedQuantity || 0) - alreadyDispatched,
  );
  return Math.min(approved, remainingOrder);
}

export default function CreateDispatchPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const queryClient = useQueryClient();
  const workOrderId = searchParams.get("workOrderId");

  // Form State
  const [deliveryAddresses, setDeliveryAddresses] = useState<Record<string, string>>({});
  const [totalWeight, setTotalWeight] = useState<number>(0);
  const [vehicleNumber, setVehicleNumber] = useState("");
  const [driverName, setDriverName] = useState("");
  const [driverPhone, setDriverPhone] = useState("");
  const [transporterName, setTransporterName] = useState("");
  const [dispatchRemarks, setDispatchRemarks] = useState("");
  const [expectedDeliveryDate, setExpectedDeliveryDate] = useState("");
  const [invoiceNumber, setInvoiceNumber] = useState("");
  const [ewayBillNumber, setEwayBillNumber] = useState("");
  const [actualFreightPaidAmount, setActualFreightPaidAmount] =
    useState<number>(0);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [dispatchQuantities, setDispatchQuantities] = useState<
    Record<string, number>
  >({});
  const [documentFile, setDocumentFile] = useState<File | null>(null);
  const [documentPreview, setDocumentPreview] = useState<string | null>(null);
  const initialSelectionSet = React.useRef(false);

  // Fetch the complete pending queue so multiple compatible lines can be
  // consolidated into one dispatch.
  const {
    data: workOrders = [],
    isLoading,
    error,
  } = useQuery<WorkOrder[]>({
    queryKey: ["pending-dispatch-work-orders-create"],
    queryFn: async () => {
      const payload = await backendFetch<WorkOrder[]>(
        "/api/backend/production/work-orders?status=READY_FOR_DISPATCH",
      );
      return Array.isArray(payload) ? payload : [];
    },
  });

  useEffect(() => {
    if (!workOrders.length || initialSelectionSet.current) return;
    const initial =
      workOrders.find((row) => row.id === workOrderId) || workOrders[0];
    setSelectedIds([initial.id]);
    setDispatchQuantities({ [initial.id]: availableQuantity(initial) });
    initialSelectionSet.current = true;
  }, [workOrders, workOrderId]);

  const selectedWorkOrders = React.useMemo(
    () => workOrders.filter((row) => selectedIds.includes(row.id)),
    [workOrders, selectedIds]
  );
  const selectedSalesOrders = React.useMemo(
    () =>
      Array.from(
        new Map(
          selectedWorkOrders
            .map((row) => row.productionPlan?.salesOrder)
            .filter((row): row is SalesOrder => Boolean(row))
            .map((row) => [row.id, row]),
        ).values(),
      ),
    [selectedWorkOrders]
  );
  const transportationCost = selectedSalesOrders.reduce(
    (sum, order) => sum + Number(order.freightAmount || 0),
    0,
  );
  const workOrder = selectedWorkOrders[0];
  const salesOrder = workOrder?.productionPlan?.salesOrder;
  const customer = salesOrder?.customer;

  // Prefill default delivery addresses per selected Sales Order
  useEffect(() => {
    if (!selectedSalesOrders.length) return;

    setDeliveryAddresses((current) => {
      let hasChanges = false;
      const updated = { ...current };
      for (const order of selectedSalesOrders) {
        if (updated[order.id] === undefined) {
          updated[order.id] = formatAddressValue(order.shippingAddress) ||
            formatAddressValue(order.customer?.shippingAddress) ||
            formatAddressValue(order.customer?.billingAddress) || "";
          hasChanges = true;
        }
      }
      return hasChanges ? updated : current;
    });

    // Prefill date using the first selected sales order if available
    const firstOrderWithDate = selectedSalesOrders.find(o => o.requestedDeliveryDate);
    if (firstOrderWithDate && !expectedDeliveryDate) {
      setExpectedDeliveryDate(new Date(firstOrderWithDate.requestedDeliveryDate || Date.now()).toISOString().slice(0, 10));
    }
  }, [selectedSalesOrders, expectedDeliveryDate]);

  const toggleWorkOrder = (candidate: WorkOrder) => {
    setSelectedIds((current) => {
      if (current.includes(candidate.id)) {
        return current.filter((id) => id !== candidate.id);
      }
      return [...current, candidate.id];
    });
    setDispatchQuantities((current) => ({
      ...current,
      [candidate.id]: current[candidate.id] ?? availableQuantity(candidate),
    }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setDocumentFile(file);
      if (file.type.startsWith("image/")) {
        const reader = new FileReader();
        reader.onloadend = () => {
          setDocumentPreview(reader.result as string);
        };
        reader.readAsDataURL(file);
      } else {
        setDocumentPreview(null);
      }
    } else {
      setDocumentFile(null);
      setDocumentPreview(null);
    }
  };

  const handleSubmit = async () => {
    if (!selectedWorkOrders.length) {
      toast.error("Select at least one pending dispatch order");
      return;
    }
    if (
      !Number.isFinite(actualFreightPaidAmount) ||
      actualFreightPaidAmount < 0
    ) {
      toast.error("Actual Paid Amount cannot be negative");
      return;
    }
    for (const selected of selectedWorkOrders) {
      const quantity = Number(dispatchQuantities[selected.id] || 0);
      const maximum = availableQuantity(selected);
      if (quantity <= 0 || quantity > maximum) {
        toast.error(
          `${selected.workOrderNumber}: quantity must be between 1 and ${maximum}`,
        );
        return;
      }
    }

    try {
      const orderGroups = selectedWorkOrders.reduce((groups, selected) => {
        const selectedSalesOrder = selected.productionPlan?.salesOrder;
        if (!selectedSalesOrder?.id) return groups;
        const group = groups.get(selectedSalesOrder.id) || {
          salesOrder: selectedSalesOrder,
          workOrders: [] as WorkOrder[],
        };
        group.workOrders.push(selected);
        groups.set(selectedSalesOrder.id, group);
        return groups;
      }, new Map<string, { salesOrder: SalesOrder; workOrders: WorkOrder[] }>());

      for (const group of orderGroups.values()) {
        const groupAddress = deliveryAddresses[group.salesOrder.id] || "";
        if (!groupAddress.trim()) {
          throw new Error(
            `Delivery address is missing for ${group.salesOrder.orderNumber}`,
          );
        }
      }

      for (const group of orderGroups.values()) {
        const consolidatedItems = Array.from(
          group.workOrders.reduce((items, selected) => {
          const itemId = selected.salesOrderItem?.id;
          if (!itemId) return items;
          const current = items.get(itemId) || {
            salesOrderItemId: itemId,
            quantity: 0,
            workOrderIds: [] as string[],
          };
          current.quantity += Number(dispatchQuantities[selected.id]);
          current.workOrderIds.push(selected.id);
          items.set(itemId, current);
          return items;
          }, new Map<string, { salesOrderItemId: string; quantity: number; workOrderIds: string[] }>())
          .values(),
        );
        const groupAddress = deliveryAddresses[group.salesOrder.id] || "";

        const payload = {
            salesOrderId: group.salesOrder.id,
            deliveryAddress: groupAddress,
            totalWeight: Number(totalWeight) || 0,
            vehicleNumber,
            transporterName,
            driverName,
            driverPhone,
            dispatchRemarks,
            expectedDeliveryDate:
              group.salesOrder.requestedDeliveryDate ||
              expectedDeliveryDate ||
              undefined,
            invoiceNumber,
            ewayBillNumber,
            freightAmount:
              transportationCost > 0
                ? (actualFreightPaidAmount *
                    Number(group.salesOrder.freightAmount || 0)) /
                  transportationCost
                : actualFreightPaidAmount / orderGroups.size,
            items: consolidatedItems,
          };

          console.log("Sending dispatch data:", payload);

          await backendFetch<unknown>("/api/backend/logistics/dispatches", {
            method: "POST",
            body: payload,
          });
      }

      toast.success(
        orderGroups.size === 1
          ? "Dispatch created and marked In Transit"
          : `${orderGroups.size} sales orders added to this dispatch run`,
      );
      queryClient.invalidateQueries({ queryKey: ["in-transit-dispatches"] });
      router.push("/dispatch/in-transit");
    } catch (err: any) {
      console.error(
        "Create dispatch failed. Exact Backend Message:\n" +
          (err?.details?.message?.join?.("\n") ||
            err?.details?.message ||
            err?.message ||
            "Unknown error")
      );

      alert(
        err?.details?.message?.join?.("\n") ||
          err?.details?.message ||
          err?.message ||
          "Failed to create dispatch"
      );
    }
  };

  if (isLoading) {
    return (
      <div className={styles.page} style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: "60vh", color: "#64748b", fontSize: 14, gap: 10 }}>
        <Truck style={{ animation: "spin 1s linear infinite", width: 22, height: 22, color: "#3b82f6" }} />
        Loading work order details...
      </div>
    );
  }

  if (error || (!isLoading && workOrders.length === 0)) {
    return (
      <div className={styles.page}>
        <div style={{ maxWidth: 480, margin: "40px auto", padding: 24, background: "#fef2f2", border: "1px solid #fecaca", borderRadius: 14 }}>
          <h1 style={{ fontSize: 16, fontWeight: 700, color: "#991b1b", margin: "0 0 8px" }}>Error loading work order</h1>
          <p style={{ fontSize: 13, color: "#b91c1c", margin: "0 0 16px" }}>No work orders are currently ready for dispatch.</p>
          <button onClick={() => router.push("/dispatch/orders")} style={{ padding: "8px 16px", borderRadius: 8, border: "1px solid #fca5a5", background: "#fff", color: "#b91c1c", fontWeight: 700, cursor: "pointer", fontSize: 13 }}>
            Back to Queue
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.page}>
      {/* ΓöÇΓöÇ Top Header ΓöÇΓöÇ */}
      <div className={styles.topBar}>
        <h1 className={styles.pageTitle}>Schedule Outgoing Shipment (Fulfillment Booking)</h1>
        <button type="button" className={styles.cancelBtn} onClick={() => router.push("/dispatch/orders")}>
          Cancel
        </button>
      </div>

      <div className={styles.card}>
        {/* ΓöÇΓöÇ Top Section: Order List + Cargo Summary ΓöÇΓöÇ */}
        <div className={styles.topSection}>

          {/* Left: Select Active Order Reference */}
          <div className={styles.orderListPanel}>
            <p className={styles.panelLabel}>Select Active Order Reference</p>
            <div className={styles.orderList}>
              {workOrders.map((candidate) => {
                const candidateSalesOrder = candidate.productionPlan?.salesOrder;
                const selected = selectedIds.includes(candidate.id);
                const maximum = availableQuantity(candidate);
                return (
                  <label
                    key={candidate.id}
                    className={`${styles.orderItem} ${selected ? styles.selected : ""}`.trim()}
                    style={maximum <= 0 ? { opacity: 0.45, cursor: "not-allowed" } : {}}
                  >
                    <input
                      type="checkbox"
                      checked={selected}
                      disabled={maximum <= 0}
                      onChange={() => toggleWorkOrder(candidate)}
                    />
                    <span>
                      {candidateSalesOrder?.orderNumber || candidate.workOrderNumber}{" "}
                      ({maximum} Units)
                    </span>
                  </label>
                );
              })}
            </div>
          </div>

          {/* Right: Cargo & Ordered Items Summary */}
          <div className={styles.cargoPanel}>
            <div className={styles.cargoHeader}>
              <div className={styles.cargoTitle}>
                <ClipboardList size={15} />
                Cargo &amp; Ordered Items Summary
              </div>
              <div className={styles.cargoActions}>
                <button type="button" className={styles.cargoActionBtn}>Auto Fill 1 each</button>
                <button type="button" className={styles.cargoActionBtn}>Distribute equally</button>
              </div>
            </div>

            <div className={styles.cargoTableWrap}>
              <table className={styles.cargoTable}>
                <thead>
                  <tr>
                    <th>Order ID</th>
                    <th className={styles.center}>Ordered</th>
                    <th className={styles.center}>Remaining</th>
                    <th className={styles.center}>Dispatch Now</th>
                  </tr>
                </thead>
                <tbody>
                  {selectedWorkOrders.map((candidate) => {
                    const candidateSalesOrder = candidate.productionPlan?.salesOrder;
                    const maximum = availableQuantity(candidate);
                    const orderedQty = candidate.salesOrderItem?.orderedQuantity || maximum;
                    return (
                      <tr key={candidate.id}>
                        <td>
                          <div className={styles.orderId}>
                            {candidateSalesOrder?.orderNumber || candidate.workOrderNumber}
                          </div>
                          <div className={styles.productName}>
                            {candidate.salesOrderItem?.productNameSnapshot || "Unknown Product"}
                          </div>
                        </td>
                        <td className={styles.center}>{orderedQty}</td>
                        <td className={`${styles.center} ${styles.remaining}`}>{maximum}</td>
                        <td className={styles.center}>
                          <input
                            type="number"
                            min={1}
                            max={maximum}
                            value={dispatchQuantities[candidate.id] ?? maximum}
                            onChange={(event) =>
                              setDispatchQuantities((current) => ({
                                ...current,
                                [candidate.id]: Number(event.target.value),
                              }))
                            }
                            className={styles.qtyInput}
                          />
                        </td>
                      </tr>
                    );
                  })}
                  {selectedWorkOrders.length === 0 && (
                    <tr>
                      <td colSpan={4} className={styles.emptyMsg}>
                        Select an order reference to view details
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>

            <div className={styles.cargoFooter}>
              <span className={styles.totalLabel}>Total Dispatch Quantity:</span>
              <span className={styles.totalBadge}>
                {selectedWorkOrders.reduce(
                  (sum, sel) => sum + Number(dispatchQuantities[sel.id] || 0),
                  0,
                )}{" "}
                Tons
              </span>
            </div>
          </div>
        </div>

        {/* ΓöÇΓöÇ Divider ΓöÇΓöÇ */}
        <div className={styles.divider} />

        {/* ΓöÇΓöÇ Delivery Addresses ΓöÇΓöÇ */}
        <div style={{ marginBottom: 32 }}>
          <h3 className="font-bold text-gray-800 flex items-center gap-2 text-sm mb-4">
            Delivery Addresses
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {selectedSalesOrders.map((order) => (
              <div key={order.id} className={styles.addressPanel}>
                <div className={styles.addressHeader}>
                  <span className={styles.addressTitle}>{order.orderNumber}</span>
                  <span className="text-[10px] uppercase tracking-wide text-blue-600 font-bold bg-blue-50 px-2 py-0.5 rounded border border-blue-100">Shipping To</span>
                </div>
                <textarea
                  className={styles.addressTextarea}
                  value={deliveryAddresses[order.id] || ""}
                  onChange={(e) => setDeliveryAddresses((curr) => ({ ...curr, [order.id]: e.target.value }))}
                  placeholder={`Delivery Address for ${order.orderNumber}...`}
                />
              </div>
            ))}
            {selectedSalesOrders.length === 0 && (
              <div className="text-sm font-medium text-gray-400 p-4 border border-dashed border-gray-200 rounded-xl text-center md:col-span-2">
                Select an order to view and edit its delivery address
              </div>
            )}
          </div>
        </div>

        {/* ΓöÇΓöÇ Form Fields Grid ΓöÇΓöÇ */}
        <div className={styles.formGrid}>

          <div className={styles.formGroup}>
            <label className={styles.formLabel}>Total Weight (Tons)<span className={styles.required}>*</span></label>
            <input
              type="number"
              min="0.1"
              step="0.1"
              value={totalWeight || ""}
              onChange={(e) => setTotalWeight(Number(e.target.value))}
              className={styles.formInput}
              placeholder="e.g. 15.5"
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.formLabel}>Vehicle No<span className={styles.required}>*</span></label>
            <input
              type="text"
              value={vehicleNumber}
              onChange={(e) => setVehicleNumber(e.target.value)}
              className={styles.formInput}
              placeholder="e.g. UK-07-CB-1234"
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.formLabel}>Driver Name<span className={styles.required}>*</span></label>
            <input
              type="text"
              value={driverName}
              onChange={(e) => setDriverName(e.target.value)}
              className={styles.formInput}
              placeholder="e.g. Ramesh Singh"
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.formLabel}>Driver Phone</label>
            <input
              type="tel"
              value={driverPhone}
              onChange={(e) => setDriverPhone(e.target.value)}
              className={styles.formInput}
              placeholder="e.g. 9876543210"
            />
          </div>
          <div className={styles.formGroup}>
            <label className={styles.formLabel}>Dispatch Remarks</label>
            <input
              type="text"
              value={dispatchRemarks}
              onChange={(e) => setDispatchRemarks(e.target.value)}
              className={styles.formInput}
              placeholder="e.g. Fragile items loaded carefully"
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.formLabel}>Courier / Transport<span className={styles.required}>*</span></label>
            <input
              type="text"
              value={transporterName}
              onChange={(e) => setTransporterName(e.target.value)}
              className={styles.formInput}
              placeholder="e.g. Himalaya Own Fleet / DTDC"
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.formLabel}>LR / AWB Number</label>
            <input
              type="text"
              value={ewayBillNumber}
              onChange={(e) => setEwayBillNumber(e.target.value)}
              className={styles.formInput}
              placeholder="e.g. LR-2024-00123"
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.formLabel}>Dispatch Date<span className={styles.required}>*</span></label>
            <input
              type="date"
              value={expectedDeliveryDate}
              onChange={(e) => setExpectedDeliveryDate(e.target.value)}
              className={styles.formInput}
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.formLabel}>Fetched Transportation Cost (Γé╣)</label>
            <input
              type="number"
              value={transportationCost || ""}
              readOnly
              disabled
              className={styles.formInput}
              style={{ backgroundColor: "#f8fafc", cursor: "not-allowed", color: "#94a3b8" }}
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.formLabel}>To Be Paid (Γé╣)</label>
            <input
              type="number"
              value={actualFreightPaidAmount || ""}
              onChange={(e) => setActualFreightPaidAmount(Number(e.target.value))}
              className={styles.formInput}
              placeholder="e.g. 500.00"
            />
          </div>

          <div className={`${styles.formGroup} ${styles.span2}`}>
            <label className={styles.formLabel}>Dispatch Document (PDF / Image)</label>
            <label className={styles.fileInput}>
              <span className={styles.fileInputBtn}>Choose File</span>
              <span className={styles.fileInputText}>
                {documentFile ? documentFile.name : "No file chosen"}
              </span>
              <input 
                type="file" 
                accept="image/*,.pdf" 
                style={{ display: "none" }} 
                onChange={handleFileChange}
              />
            </label>
            {documentPreview && (
              <div style={{ marginTop: 12 }}>
                <img 
                  src={documentPreview} 
                  alt="Document Preview" 
                  style={{ maxWidth: "200px", maxHeight: "200px", borderRadius: "8px", border: "1px solid #e2e8f0", objectFit: "contain" }} 
                />
              </div>
            )}
            {documentFile && !documentPreview && (
               <div style={{ marginTop: 12, fontSize: 13, color: '#64748b' }}>
                 Preview not available for this file type.
               </div>
            )}
          </div>

        </div>

        {/* ΓöÇΓöÇ Submit ΓöÇΓöÇ */}
        <div className={styles.submitRow}>
          <button
            type="button"
            onClick={handleSubmit}
            disabled={selectedWorkOrders.length === 0}
            className={styles.submitBtn}
          >
            Book Dispatch Consignment
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { PackageOpen, ArrowRight, Truck, CheckCircle, Upload, Navigation, Plus } from 'lucide-react';
import { toast } from 'sonner';
import styles from './sample-dispatch.module.css';

const INITIAL_MOCK_REQUESTS = [
  {
    id: 'req-1',
    orderNo: '#SO-2026-00007',
    customer: 'Lifecycle Customer MS4J0RRM',
    address: 'N/A',
    product: 'Lifecycle Product MS4J0RRM',
    approvedQty: 4,
    status: 'pending',
    deliveryState: 'Not Started'
  },
  {
    id: 'req-2',
    orderNo: '#SO-2026-00008',
    customer: 'Alpha Tech Solutions',
    address: '45 Industrial Park, Mumbai',
    product: 'Sample Beta Prototype X1',
    approvedQty: 10,
    status: 'in-transit',
    deliveryState: 'Not Started'
  },
  {
    id: 'req-3',
    orderNo: '#SO-2026-00009',
    customer: 'Global Logistics Corp',
    address: '112 Transport Nagar, Delhi',
    product: 'Evaluation Kit Standard',
    approvedQty: 2,
    status: 'delivered',
    deliveryState: 'Delivered'
  }
];

function SampleDispatchListContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [filter, setFilter] = useState('pending');
  const [requests, setRequests] = useState(INITIAL_MOCK_REQUESTS);

  const [uploadModalOpen, setUploadModalOpen] = useState(false);
  const [uploadingSampleId, setUploadingSampleId] = useState<string | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  // Sync state with URL if user provides ?status=xxx
  useEffect(() => {
    const statusParam = searchParams?.get('status');
    if (statusParam && ['pending', 'in-transit', 'delivered', 'all'].includes(statusParam)) {
      setFilter(statusParam);
    }
  }, [searchParams]);

  // Fetch live samples from the backend API
  useEffect(() => {
    let isMounted = true;
    const fetchSamples = async () => {
      try {
        const { apiClient } = await import('@/lib/apiClient');
        const res = await apiClient.get('/api/backend/sales/samples');

        const dataArray = Array.isArray(res?.data) ? res.data : (Array.isArray(res) ? res : []);

        if (isMounted && dataArray.length > 0) {
          const liveSamples = dataArray.map((sample: any) => ({
            id: sample.id ? `req-${sample.id}` : `req-${sample.sampleId}`,
            orderNo: sample.sampleNumber || sample.sampleId || `#SMP-${sample.id}`,
            customer: sample.customer || sample.customerName || sample.companyName || sample.leadName || 'Unknown Customer',
            address: sample.address || 'See Lead/Customer address',
            product: sample.product || sample.productName || sample.products?.[0]?.productName || 'Sample Product',
            approvedQty: sample.quantity || sample.products?.[0]?.quantity || 1,
            status: sample.status?.toLowerCase() === 'dispatched' || sample.status?.toLowerCase() === 'in-transit' ? 'in-transit' : 
                    sample.status?.toLowerCase() === 'delivered' ? 'delivered' : 
                    sample.status?.toLowerCase() === 'completed' ? 'completed' :
                    sample.status?.toLowerCase() === 'return_requested' ? 'pending' :
                    sample.status?.toLowerCase() === 'return_in_transit' ? 'in-transit' :
                    sample.status?.toLowerCase() === 'returned' ? 'completed' : 'pending',
            isReturn: sample.status?.toLowerCase() === 'return_requested' || 
                      sample.status?.toLowerCase() === 'return_in_transit' ||
                      sample.status?.toLowerCase() === 'returned',
            deliveryState: sample.status?.toLowerCase() === 'delivered' ? 'Delivered' :
                           sample.status?.toLowerCase() === 'return_in_transit' ? 'Return In Transit' :
                           sample.status?.toLowerCase() === 'returned' ? 'Returned' :
                           sample.status?.toLowerCase() === 'dispatched' ? 'Out for Delivery' : 'Not Started'
          }));

          setRequests(prev => {
            const prevIds = new Set(prev.map(p => p.id));
            const newLive = liveSamples.filter((s: any) => !prevIds.has(s.id));
            return [...newLive, ...prev];
          });
        }
      } catch (err) {
        console.warn('Failed to fetch live sample requests', err);
      }
    };
    fetchSamples();
    return () => { isMounted = false; };
  }, []);

  const setUrlFilter = (newFilter: string) => {
    setFilter(newFilter);
    router.push(`/dispatch/sample-dispatch?status=${newFilter}`);
  };

  const updateDeliveryState = async (id: string, newState: string) => {
    try {
      const { apiClient } = await import('@/lib/apiClient');
      const sampleId = id.replace('req-', '');
      const req = requests.find(r => r.id === id);
      const isReturn = (req as any)?.isReturn;

      if (newState === 'Started') {
        await apiClient.patch(`/api/backend/sales/samples/${sampleId}`, {
          status: isReturn ? 'RETURN_IN_TRANSIT' : 'DISPATCHED',
          deliveryState: 'Started'
        });
      } else if (newState === 'Delivered') {
        await apiClient.patch(`/api/backend/sales/samples/${sampleId}`, {
          status: isReturn ? 'RETURNED' : 'DELIVERED',
          deliveryState: isReturn ? 'Returned' : 'Delivered'
        });
      }

      setRequests(prev => prev.map(r => {
        if (r.id === id) {
          if (newState === 'Delivered') {
            return { ...r, deliveryState: isReturn ? 'Returned' : 'Delivered', status: isReturn ? 'completed' : 'delivered' };
          }
          return { ...r, deliveryState: newState, status: isReturn ? 'in-transit' : r.status };
        }
        return r;
      }));
      if (newState === 'Delivered') {
        setUrlFilter(isReturn ? 'all' : 'delivered');
      }
    } catch (e) {
      console.warn('Failed to update delivery state in backend', e);
    }
  };

  const openUploadModal = (id: string) => {
    setUploadingSampleId(id);
    setUploadModalOpen(true);
    setSelectedFile(null);
    setPreviewUrl(null);
  };

  const closeUploadModal = () => {
    setUploadModalOpen(false);
    setUploadingSampleId(null);
    setSelectedFile(null);
    setPreviewUrl(null);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedFile(file);
      const url = URL.createObjectURL(file);
      setPreviewUrl(url);
    }
  };

  const confirmUpload = async () => {
    if (!selectedFile || !uploadingSampleId) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      try {
        const { apiClient } = await import('@/lib/apiClient');
        const sampleId = uploadingSampleId.replace('req-', '');
        await apiClient.patch(`/api/backend/sales/samples/${sampleId}`, { 
          proofOfDelivery: reader.result,
          status: 'COMPLETED'
        });

        setRequests(prev => prev.map(req => 
          req.id === uploadingSampleId ? { ...req, status: 'completed' } : req
        ));

        toast.success('Proof of delivery uploaded successfully!');
        closeUploadModal();
      } catch (err) {
        console.error(err);
        toast.error('Failed to upload proof');
      }
    };
    reader.readAsDataURL(selectedFile);
  };

  const filteredRequests = filter === 'all' ? requests : requests.filter(req => req.status === filter);

  return (
    <div className={styles.page}>
      <div className={styles.content}>

        {/* ΓöÇΓöÇ Page Header ΓöÇΓöÇ */}
        <div className={styles.header}>
          <div className={styles.headerMain}>
            <div className={styles.watermark}>
              <PackageOpen size={160} />
            </div>

            <div className={styles.headerLayout}>
              <div className={styles.headerCopy}>
                <span className={styles.eyebrow}>Logistics Queue</span>
                <h1 className={styles.title}>Sample Dispatch Requests</h1>
                <p className={styles.description}>
                  Manage all pending requests for product samples and evaluation kits. Review approved quantities and initialize the dispatch tracking workflow.
                </p>
              </div>

              <div className={styles.summary}>
                <div className={styles.summaryCount}>
                  <strong>{requests.filter(r => r.status === 'pending').length}</strong>
                  <span>Pending</span>
                </div>
                <div style={{ width: 1, height: 40, background: 'rgba(255,255,255,0.2)' }} />
                <div className={styles.summaryCount}>
                  <strong>{requests.filter(r => r.status === 'in-transit').length}</strong>
                  <span>In-Transit</span>
                </div>
              </div>
            </div>
          </div>

          <div className={styles.headerFooter}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
              <span>Showing {filteredRequests.length} request{filteredRequests.length !== 1 ? 's' : ''} in queue</span>
              <button 
                onClick={() => router.push('/dispatch/sample-dispatch/create/new')}
                style={{ 
                  display: 'flex', alignItems: 'center', gap: 6, 
                  background: '#2563eb', color: 'white', border: 'none', 
                  padding: '6px 14px', borderRadius: 8, fontSize: 13, 
                  fontWeight: 600, cursor: 'pointer' 
                }}
              >
                <Plus style={{ width: 14, height: 14 }} /> Create Ad-hoc Sample
              </button>
            </div>
          </div>
        </div>

        {/* ΓöÇΓöÇ Filters ΓöÇΓöÇ */}
        <div className={styles.filters}>
          <button 
            className={`${styles.filterTab} ${filter === 'pending' ? styles.active : ''}`}
            onClick={() => setUrlFilter('pending')}
          >
            Pending Dispatch
          </button>
          <button 
            className={`${styles.filterTab} ${filter === 'in-transit' ? styles.active : ''}`}
            onClick={() => setUrlFilter('in-transit')}
          >
            In-Transit
          </button>
          <button 
            className={`${styles.filterTab} ${filter === 'delivered' ? styles.active : ''}`}
            onClick={() => setUrlFilter('delivered')}
          >
            Delivered
          </button>
          <button 
            className={`${styles.filterTab} ${filter === 'all' ? styles.active : ''}`}
            onClick={() => setUrlFilter('all')}
          >
            All History
          </button>
        </div>

        {/* ΓöÇΓöÇ Data Table ΓöÇΓöÇ */}
        <div className={styles.tableContainer}>
          <div className={styles.tableScroll}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>Sample Order</th>
                  <th>Customer</th>
                  <th>Delivery Address</th>
                  <th>Product</th>
                  <th>Approved Qty</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredRequests.length > 0 ? (
                  filteredRequests.map(req => (
                    <tr key={req.id}>
                      <td className={styles.tableRowId}>
                        {req.orderNo}
                        {(req as any).isReturn && (
                          <span style={{ marginLeft: 6, background: '#fef2f2', color: '#b91c1c', border: '1px solid #fecaca', borderRadius: 4, padding: '1px 6px', fontSize: 10, fontWeight: 800, letterSpacing: 0.3 }}>Γå⌐ RETURN</span>
                        )}
                      </td>
                      <td style={{ fontWeight: 600 }}>{req.customer}</td>
                      <td>
                        {req.address !== 'N/A' ? (
                          <span style={{ color: '#475569' }}>{req.address}</span>
                        ) : (
                          <span style={{ color: '#94a3b8', fontStyle: 'italic' }}>Not provided</span>
                        )}
                      </td>
                      <td style={{ fontWeight: 600, color: '#334155' }}>{req.product}</td>
                      <td>
                        <span style={{ background: '#f1f5f9', padding: '4px 8px', borderRadius: '4px', fontWeight: 700 }}>
                          {req.approvedQty}
                        </span>
                      </td>
                      <td>
                        {req.status === 'pending' && (
                          <button 
                            className={styles.tableActionBtn}
                            style={(req as any).isReturn ? { background: '#fef2f2', borderColor: '#fecaca', color: '#b91c1c' } : {}}
                            onClick={() => router.push(`/dispatch/sample-dispatch/create/${req.id}`)}
                          >
                            {(req as any).isReturn ? 'Γå⌐ Arrange Pick-up' : 'Dispatch'} <ArrowRight style={{ width: 14, height: 14 }} />
                          </button>
                        )}
                        {req.status === 'in-transit' && (req.deliveryState === 'Not Started' || req.deliveryState === 'Out for Delivery' || req.deliveryState === 'Return In Transit') && (
                          <button 
                            className={styles.tableActionBtn}
                            style={{ background: '#eff6ff', borderColor: '#bfdbfe', color: '#1d4ed8' }}
                            onClick={() => updateDeliveryState(req.id, 'Started')}
                          >
                            <Navigation style={{ width: 14, height: 14 }} /> {(req as any).isReturn ? 'Start Pick-up' : 'Start Delivery'}
                          </button>
                        )}
                        {req.status === 'in-transit' && req.deliveryState === 'Started' && (
                          <button 
                            className={styles.tableActionBtn}
                            style={{ background: '#f0fdf4', borderColor: '#bbf7d0', color: '#15803d' }}
                            onClick={() => updateDeliveryState(req.id, 'Delivered')}
                          >
                            <CheckCircle style={{ width: 14, height: 14 }} /> {(req as any).isReturn ? 'Confirm Return' : 'Confirm Delivery'}
                          </button>
                        )}
                        {req.status === 'delivered' && (
                          <button 
                            className={styles.tableActionBtn}
                            style={{ color: '#475569' }}
                            onClick={() => openUploadModal(req.id)}
                          >
                            <Upload style={{ width: 14, height: 14 }} /> Upload Proof
                          </button>
                        )}
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={6} style={{ textAlign: 'center', padding: '40px', color: '#94a3b8' }}>
                      No {filter} sample dispatch requests found.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

      </div>

      {uploadModalOpen && (
        <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.5)', zIndex: 9999, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ background: '#fff', padding: '24px', borderRadius: '12px', width: '400px', maxWidth: '90%', boxShadow: '0 10px 25px rgba(0,0,0,0.2)' }}>
            <h3 style={{ margin: '0 0 16px 0', fontSize: '18px', fontWeight: 'bold' }}>Upload Proof of Delivery</h3>

            <div style={{ border: '2px dashed #cbd5e1', padding: '20px', textAlign: 'center', borderRadius: '8px', marginBottom: '20px', position: 'relative' }}>
              {previewUrl ? (
                <img src={previewUrl} alt="Preview" style={{ maxWidth: '100%', maxHeight: '200px', objectFit: 'contain' }} />
              ) : (
                <div style={{ color: '#64748b' }}>
                  <Upload style={{ width: 32, height: 32, marginBottom: '8px', color: '#94a3b8' }} />
                  <p style={{ margin: 0, fontSize: '14px' }}>Click to select an image</p>
                </div>
              )}
              <input 
                type="file" 
                accept="image/*"
                onChange={handleFileSelect}
                style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', opacity: 0, cursor: 'pointer' }}
              />
            </div>

            <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
              <button 
                onClick={closeUploadModal}
                style={{ padding: '8px 16px', border: '1px solid #cbd5e1', background: '#fff', borderRadius: '6px', cursor: 'pointer', fontWeight: '600' }}
              >
                Cancel
              </button>
              <button 
                onClick={confirmUpload}
                disabled={!selectedFile}
                style={{ padding: '8px 16px', border: 'none', background: selectedFile ? '#3b82f6' : '#94a3b8', color: '#fff', borderRadius: '6px', cursor: selectedFile ? 'pointer' : 'not-allowed', fontWeight: '600' }}
              >
                Done
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

